def controller_traceback_projection(error, registry):
    """Project actual in-process traceback locations, never locals or raw text.

    Controller admission can fail after a successful child. Child streams do
    not contain that traceback. Exact file pins and public AST declarations
    gate every location and static message exposed here.
    """
    frames, templates = [], []
    unknown, truncated = 0, False
    tb = error.__traceback__
    visited = 0
    while tb is not None:
        if visited >= MAX_FRAMES:
            truncated = True
            break
        visited += 1
        try:
            frame = source_frame(tb.tb_frame.f_code.co_filename, tb.tb_lineno, registry)
        except Exception:
            frame = None
        if frame is None:
            unknown += 1
        else:
            frames.append(frame)
            templates.extend(frame['static_error_templates'])
        tb = tb.tb_next
    message = str(error)
    exact = message if message in templates and '<dynamic>' not in message else None
    return {'category': type(error).__name__ if type(error).__name__ in ERRORS else 'unrecognized',
            'message_sha256': identity(message.encode())['sha256'],
            'verified_static_message': exact, 'frames': frames,
            'unknown_frames': unknown, 'truncated': truncated,
            'scope': 'controller exception; distinct from child lifecycle and streams',
            'source_templates_are_declarations_not_dynamic_values': True}


